from django.db import migrations, models

OLD_PREFIX = "📢 Bulletin from your landlord\n\n"
EVENT_MARK = "\n\n📅 "


def mark_old_bulletins(apps, schema_editor):
    """Bulletins sent before this change were plain messages starting with
    "📢 Bulletin from your landlord": make them bulletin banners."""
    Message = apps.get_model("core_inquiries", "Message")
    for message in Message.objects.filter(body__startswith=OLD_PREFIX):
        body = message.body[len(OLD_PREFIX):]
        event = ""
        if EVENT_MARK in body:
            body, event = body.rsplit(EVENT_MARK, 1)
        message.kind = "bulletin"
        message.body = body.strip()
        message.bulletin_event = event.strip()[:200]
        message.save(update_fields=["kind", "body", "bulletin_event"])


